<template><div class="merchant-login"><section class="login-editorial"><div class="login-wordmark">SUXU</div><span>MERCHANT ATELIER</span><h1>让美好相伴。<br>让热爱有序。</h1><img :src="heroImage" alt="素序布包与首饰系列"><small>THE ART OF EVERYDAY OBJECTS.</small></section><section class="login-side"><el-form class="merchant-login-form" @submit.native.prevent="submit"><span class="eyebrow">WELCOME TO YOUR ATELIER</span><h2>欢迎回到素序</h2><p>登录商家工作室，开启今天的精品日常。</p><el-form-item label="商家账号"><el-input aria-label="商家账号" v-model="form.username" autocomplete="username" maxlength="60" placeholder="请输入商家账号"></el-input></el-form-item><el-form-item label="登录密码"><el-input aria-label="登录密码" v-model="form.password" type="password" autocomplete="current-password" show-password maxlength="200" placeholder="请输入密码"></el-input></el-form-item><el-button native-type="submit" type="primary" :loading="busy" class="full">登录工作室 <i class="el-icon-right"></i></el-button><small>独立管理端 · 仅限授权商家访问</small></el-form></section></div></template>
<script>
import {login} from '@/api/auth'
export default{data:()=>({heroImage:process.env.BASE_URL+'images/hero.jpg',form:{username:'admin',password:''},busy:false}),methods:{async submit(){if(this.busy)return;this.busy=true;try{const data=await login(this.form);this.$store.commit('UBD/setSession',data);this.form.password='';this.$router.replace('/orders')}catch(e){this.$message.error(e.message)}finally{this.busy=false}}}}
</script>
